1	<script setup lang="ts">
2	/**
3	 * Compact conversation list (UX-01).
4	 *
5	 * - Focus is an explicit account-scoped conversation reference, never an array
6	 *   position and never bulk selection: rows use ordinary list/listitem
7	 *   semantics with roving tabindex and `aria-current` (not `aria-selected`),
8	 *   so a future selection model can diverge from focus.
9	 * - Row keys are account+conversation; DOM refs and navigation address
10	 *   conversations only. Date group headings are non-actionable and never
11	 *   tabbable, and they never reorder the backend's rows.
12	 * - Hover changes nothing: no hover handler mutates focus or read state.
13	 *   Inline actions are row-scoped buttons that stop propagation; focusing one
14	 *   never opens the row or scrolls it to center.
15	 * - Anchor capture/restoration supports the reader round trip: a visible-row
16	 *   reference with its relative offset plus a scrollTop fallback.
17	 */
18	import { computed, nextTick, onBeforeUnmount, onBeforeUpdate, onMounted, reactive, ref, watch } from 'vue';
19	import type { ConversationRef } from '../lib/ipc/client';
20	import type { ConversationSummaryLike } from '../composables/useMailbox';
21	import { sameConversation } from '../composables/useMailbox';
22	import { actionLabel } from '../lib/browsing-actions';
23	import { compactDateLabel, dateGroupCaption, dateGroupFor } from '../lib/browsing-dates';
24	
25	const props = defineProps<{
26	  rows: ConversationSummaryLike[];
27	  context?: 'inbox' | 'saved' | 'done' | 'starred' | 'search';
28	  focusedRef: ConversationRef | null;
29	  actionsEnabled?: boolean;
30	  showReadState?: boolean;
31	  showReadControls?: boolean;
32	  /** UX-05: selected references (account-scoped); selection ≠ focus. */
33	  selectedRefs?: ConversationRef[];
34	}>();
35	
36	const emit = defineEmits<{
37	  focus: [ref: ConversationRef];
38	  open: [ref: ConversationRef];
39	  archive: [ref: ConversationRef];
40	  unarchive: [ref: ConversationRef];
41	  setRead: [ref: ConversationRef, read: boolean];
42	  /** X / checkbox / Cmd-click: toggle one row (the parent moves focus/anchor). */
43	  selectToggle: [ref: ConversationRef];
44	  /** Shift-click / Cmd+Shift-click: additive anchor→row range. */
45	  selectRange: [ref: ConversationRef];
46	}>();
47	
48	const selectedKeys = computed(() => new Set((props.selectedRefs ?? []).map((ref) => `${ref.accountId}:${ref.conversationId}`)));
49	
50	function isSelected(row: ConversationSummaryLike): boolean {
51	  return selectedKeys.value.has(`${row.ref.accountId}:${row.ref.conversationId}`);
52	}
53	
54	/** Pointer click on a row: Cmd/Ctrl toggles, Shift/Cmd+Shift ranges, plain opens. */
55	function onRowClick(event: MouseEvent, row: ConversationSummaryLike): void {
56	  if (event.shiftKey) {
57	    emit('selectRange', row.ref);
58	    return;
59	  }
60	  if (event.metaKey || event.ctrlKey) {
61	    emit('selectToggle', row.ref);
62	    return;
63	  }
64	  emit('open', row.ref);
65	}
66	
67	/** A surviving list row plus the geometry needed to restore it. */
68	export interface RowAnchor {
69	  ref: ConversationRef;
70	  /** Row top relative to the scrollport top at capture time. */
71	  offsetTop: number;
72	  /** Scrollport scrollTop at capture time (fallback when geometry is unavailable). */
73	  scrollTop: number;
74	}
75	
76	const listEl = ref<HTMLElement | null>(null);
77	const rowEls = new Map<string, HTMLElement>();
78	let lastFocusedKey: string | null = null;
79	let listHasFocus = false;
80	/** Guard so preventScroll focus does not trigger the focusin reveal. */
81	let preventScrollReveal = false;
82	
83	/*
84	 * Adaptive compact action presentation: when a row's full inline metadata and
85	 * actions do not fit its laid-out width (larger user text, longer dates, the
86	 * 1000px contact breakpoint), the row keeps its one-line scanning rhythm by
87	 * collapsing the action buttons behind a small disclosure control. Read state,
88	 * pending, and date stay visible; the collapsed buttons keep their stable
89	 * data-test ids, accessible names, and event semantics — only their container
90	 * moves out of flow (measured while hidden, then shown as a row-anchored
91	 * disclosure panel while the toggle is operated).
92	 */
93	const compactRows = reactive(new Set<string>());
94	const openActionRows = reactive(new Set<string>());
95	/** Rows whose open disclosure panel opens upward (near the list bottom). */
96	const upwardPanels = reactive(new Set<string>());
97	/** Panel flip threshold in row-font em: the tallest disclosed panel plus slack. */
98	const PANEL_FLIP_EM = 6;
99	/** Slack for overflow detection: scrollWidth/clientWidth round to integers. */
100	const ROW_OVERFLOW_SLACK_PX = 1;
101	let rowLayoutObserver: ResizeObserver | null = null;
102	const rowKeyByEl = new Map<HTMLElement, string>();
103	
104	type ComponentPublicInstance = import('vue').ComponentPublicInstance;
105	
106	onBeforeUpdate(() => {
107	  rowEls.clear();
108	});
109	
110	function rowKey(target: ConversationRef): string {
111	  return `${target.accountId}:${target.conversationId}`;
112	}
113	
114	function setRowRef(el: Element | ComponentPublicInstance | null, key: string): void {
115	  if (el instanceof HTMLElement) {
116	    rowEls.set(key, el);
117	    rowKeyByEl.set(el, key);
118	  }
119	}
120	
121	interface GroupItem { kind: 'group'; key: string; caption: string; id: number }
122	interface RowItem { kind: 'row'; row: ConversationSummaryLike; index: number }
123	type ListItem = GroupItem | RowItem;
124	
125	/**
126	 * Backend order is preserved; a heading is emitted wherever the calendar
127	 * bucket changes between consecutive rows (never re-sorted here).
128	 */
129	const items = computed<ListItem[]>(() => {
130	  const result: ListItem[] = [];
131	  let previousKey: string | null = null;
132	  let groupId = 0;
133	  props.rows.forEach((row, index) => {
134	    const key = dateGroupFor(row.lastMessageAt);
135	    if (key !== previousKey) {
136	      previousKey = key;
137	      groupId += 1;
138	      result.push({ kind: 'group', key, caption: dateGroupCaption(key), id: groupId });
139	    }
140	    result.push({ kind: 'row', row, index });
141	  });
142	  return result;
143	});
144	
145	function isFocused(row: ConversationSummaryLike): boolean {
146	  return sameConversation(row.ref, props.focusedRef);
147	}
148	
149	/** Roving tabindex: the focused row, else the first row, is the tab stop. */
150	function tabIndexFor(row: ConversationSummaryLike, index: number): 0 | -1 {
151	  if (isFocused(row)) return 0;
152	  if (props.focusedRef === null && index === 0) return 0;
153	  return -1;
154	}
155	
156	function senderLabel(row: ConversationSummaryLike): string {
157	  const primary = row.primaryCorrespondent;
158	  // Absent primaryCorrespondent never becomes a guessed contact.
159	  if (!primary) return 'Unknown sender';
160	  return primary.displayName ?? primary.mailbox;
161	}
162	
163	/*
164	 * Compact visible labels; the full disclosure lives in the accessible name so
165	 * the bounded metadata region never starves the subject column at the 1000px
166	 * contact breakpoint (rows render "Unknown" + Read/Unread, AT reads the
167	 * complete "Read state unknown" / "Mark read" / "Mark unread" semantics).
168	 */
169	function readStateLabel(row: ConversationSummaryLike): string {
170	  if (row.isRead === undefined) return 'Unknown';
171	  return row.isRead ? 'Read' : 'Unread';
172	}
173	
174	function hasRowActions(): boolean {
175	  return Boolean(props.showReadControls || props.actionsEnabled);
176	}
177	
178	/** DOM id of the row's action disclosure panel (for aria-controls). */
179	function actionsPanelId(row: ConversationSummaryLike): string {
180	  return `row-actions-${row.ref.accountId}-${row.ref.conversationId}`.replace(/[^A-Za-z0-9_-]/g, '-');
181	}
182	
183	function isCompactRow(row: ConversationSummaryLike): boolean {
184	  return compactRows.has(rowKey(row.ref));
185	}
186	
187	function isActionsOpen(row: ConversationSummaryLike): boolean {
188	  // Open state is tracked independently of the measured compact presentation;
189	  // CSS only reveals the panel when the row is both compact and open.
190	  return openActionRows.has(rowKey(row.ref));
191	}
192	
193	function isPanelUpward(row: ConversationSummaryLike): boolean {
194	  return upwardPanels.has(rowKey(row.ref));
195	}
196	
197	function toggleActions(row: ConversationSummaryLike): void {
198	  const key = rowKey(row.ref);
199	  if (openActionRows.has(key)) {
200	    openActionRows.delete(key);
201	    return;
202	  }
203	  openActionRows.add(key);
204	  // Open away from the nearer list edge so the panel never extends past the
205	  // list scroller's visible box when the row sits near its bottom.
206	  upwardPanels.delete(key);
207	  const el = rowEls.get(key);
208	  const scroller = listEl.value;
209	  if (!el || !scroller || scroller.clientHeight === 0 || el.clientHeight === 0) return;
210	  const em = parseFloat(getComputedStyle(el).fontSize) || 16;
211	  const below = scroller.getBoundingClientRect().bottom - el.getBoundingClientRect().bottom;
212	  if (below < PANEL_FLIP_EM * em) upwardPanels.add(key);
213	}
214	
215	function closeActions(row: ConversationSummaryLike, refocusToggle: boolean): void {
216	  const key = rowKey(row.ref);
217	  if (!openActionRows.delete(key) || !refocusToggle) return;
218	  rowEls.get(key)?.querySelector<HTMLElement>('.row-actions-toggle')?.focus();
219	}
220	
221	/**
222	 * Decide per row whether the full inline presentation fits the laid-out row.
223	 * Measured, not assumed: in the compact presentation the actions span stays in
224	 * the DOM out of flow (absolute, hidden, max-content width), so the expanded
225	 * width is exactly the current overflow measurement plus the toggle/action
226	 * width swap — no threshold guessing, no layout flip-flop. Runs synchronously
227	 * from the ResizeObserver callback, so a row never paints an overflowing
228	 * expanded layout.
229	 */
230	function evaluateRowLayout(el: HTMLElement, key: string): void {
231	  if (!el.isConnected || el.clientWidth === 0) return;
232	  const actions = el.querySelector<HTMLElement>('.row-actions');
233	  // Rows without actions never overflow into the disclosure.
234	  if (!actions) return;
235	  const toggle = el.querySelector<HTMLElement>('.row-actions-toggle');
236	  let fitsExpanded: boolean;
237	  if (compactRows.has(key)) {
238	    const actionsWidth = actions.getBoundingClientRect().width;
239	    const toggleWidth = toggle ? toggle.getBoundingClientRect().width : 0;
240	    // Strict margin: only leave the compact presentation when the expanded
241	    // layout measurably fits, so integer-rounded overflow cannot oscillate.
242	    fitsExpanded =
243	      el.scrollWidth + (actionsWidth - toggleWidth) <= el.clientWidth - ROW_OVERFLOW_SLACK_PX;
244	  } else {
245	    fitsExpanded = el.scrollWidth <= el.clientWidth + ROW_OVERFLOW_SLACK_PX;
246	  }
247	  if (fitsExpanded) compactRows.delete(key);
248	  else compactRows.add(key);
249	}
250	
251	function observeRowLayouts(): void {
252	  if (!rowLayoutObserver) return;
253	  rowLayoutObserver.disconnect();
254	  rowKeyByEl.clear();
255	  for (const [key, el] of rowEls) {
256	    rowKeyByEl.set(el, key);
257	    rowLayoutObserver.observe(el);
258	  }
259	}
260	
261	onMounted(() => {
262	  // Non-layout environments (jsdom component tests) keep the expanded
263	  // presentation; the rendered-layout regression covers the compact one.
264	  if (typeof ResizeObserver !== 'function') return;
265	  rowLayoutObserver = new ResizeObserver((entries) => {
266	    for (const entry of entries) {
267	      const el = entry.target;
268	      if (!(el instanceof HTMLElement)) continue;
269	      const key = rowKeyByEl.get(el);
270	      if (key) evaluateRowLayout(el, key);
271	    }
272	  });
273	  observeRowLayouts();
274	});
275	
276	onBeforeUnmount(() => {
277	  rowLayoutObserver?.disconnect();
278	  rowLayoutObserver = null;
279	});
280	
281	watch(
282	  () => props.rows.map((row) => rowKey(row.ref)),
283	  () => observeRowLayouts(),
284	  { flush: 'post' },
285	);
286	
287	function onFocusIn(event: FocusEvent, row: ConversationSummaryLike): void {
288	  const key = rowKey(row.ref);
289	  lastFocusedKey = key;
290	  listHasFocus = true;
291	  if (!sameConversation(row.ref, props.focusedRef)) emit('focus', row.ref);
292	  // Only the row itself scrolls; an inline button receiving focus must not
293	  // yank the row to center or reopen it. Programmatic preventScroll focus
294	  // restoration suppresses the automatic reveal so it cannot undo a caller's
295	  // (e.g. anchor-restoration) scroll positioning.
296	  if (event.target === event.currentTarget && !preventScrollReveal) revealRow(key);
297	}
298	
299	function revealRow(key: string): void {
300	  const el = rowEls.get(key);
301	  if (el && typeof el.scrollIntoView === 'function') el.scrollIntoView({ block: 'nearest' });
302	}
303	
304	function onFocusOut(event: FocusEvent): void {
305	  // Confirm asynchronously: the row may be replaced (e.g. archived out) rather than
306	  // truly losing focus; a macrotask later, re-check where focus actually lives.
307	  const rowEl = event.currentTarget;
308	  setTimeout(() => {
309	    listHasFocus = listEl.value !== null && listEl.value.contains(document.activeElement);
310	    // A row-scoped action disclosure closes when focus leaves its row, so an
311	    // open panel never lingers behind unrelated rows or surfaces.
312	    if (rowEl instanceof HTMLElement) {
313	      const key = rowKeyByEl.get(rowEl);
314	      if (key && openActionRows.has(key) && !rowEl.contains(document.activeElement)) {
315	        openActionRows.delete(key);
316	      }
317	    }
318	  }, 0);
319	}
320	
321	/**
322	 * Local Escape precedence: while the row's action disclosure is open, Escape
323	 * closes it and returns focus to the disclosure control before any app-level
324	 * Escape handling sees the event. Closed disclosures leave Escape untouched.
325	 */
326	function onRowKeydown(event: KeyboardEvent, row: ConversationSummaryLike): void {
327	  if (!openActionRows.has(rowKey(row.ref))) return;
328	  event.preventDefault();
329	  event.stopPropagation();
330	  closeActions(row, true);
331	}
332	
333	function focusRef(target: ConversationRef, options: { preventScroll?: boolean } = {}): void {
334	  const el = rowEls.get(rowKey(target));
335	  if (!el || el.closest('[inert]')) return;
336	  if (options.preventScroll) preventScrollReveal = true;
337	  el.focus({ preventScroll: options.preventScroll ?? false });
338	  preventScrollReveal = false;
339	  if (!options.preventScroll) revealRow(rowKey(target));
340	}
341	
342	function captureAnchor(): RowAnchor | null {
343	  const scroller = listEl.value;
344	  if (!scroller || props.rows.length === 0) return null;
345	  const scrollerRect = scroller.getBoundingClientRect();
346	  const rowAt = (index: number): HTMLElement | null => {
347	    const row = props.rows[index];
348	    return row ? rowEls.get(rowKey(row.ref)) ?? null : null;
349	  };
350	  // The focused row, the row holding DOM focus, or the first row at/below the
351	  // top edge — whichever is visible first.
352	  let chosen: HTMLElement | null = null;
353	  let chosenRef: ConversationRef | null = null;
354	  const active = document.activeElement;
355	  if (active instanceof HTMLElement && scroller.contains(active)) {
356	    const activeRow = active.closest('li.inbox-row');
357	    if (activeRow instanceof HTMLElement) {
358	      for (const row of props.rows) {
359	        if (rowEls.get(rowKey(row.ref)) === activeRow) {
360	          chosen = activeRow;
361	          chosenRef = row.ref;
362	          break;
363	        }
364	      }
365	    }
366	  }
367	  if (!chosen && props.focusedRef) {
368	    const focusedEl = rowEls.get(rowKey(props.focusedRef));
369	    if (focusedEl) {
370	      const rect = focusedEl.getBoundingClientRect();
371	      if (rect.bottom >= scrollerRect.top && rect.top <= scrollerRect.bottom) {
372	        chosen = focusedEl;
373	        chosenRef = props.focusedRef;
374	      }
375	    }
376	  }
377	  if (!chosen) {
378	    for (let index = 0; index < props.rows.length; index += 1) {
379	      const el = rowAt(index);
380	      if (!el) continue;
381	      const rect = el.getBoundingClientRect();
382	      if (rect.bottom >= scrollerRect.top) {
383	        chosen = el;
384	        chosenRef = props.rows[index]!.ref;
385	        break;
386	      }
387	    }
388	  }
389	  if (!chosen || !chosenRef) return null;
390	  return {
391	    ref: { ...chosenRef },
392	    offsetTop: chosen.getBoundingClientRect().top - scrollerRect.top,
393	    scrollTop: scroller.scrollTop,
394	  };
395	}
396	
397	async function restoreAnchor(anchor: RowAnchor): Promise<void> {
398	  await nextTick();
399	  const scroller = listEl.value;
400	  if (!scroller) return;
401	  const el = rowEls.get(rowKey(anchor.ref));
402	  if (!el || typeof el.getBoundingClientRect !== 'function') {
403	    scroller.scrollTop = anchor.scrollTop;
404	    return;
405	  }
406	  const scrollerRect = scroller.getBoundingClientRect();
407	  const relativeTop = el.getBoundingClientRect().top - scrollerRect.top;
408	  // Apply the measured delta to the current scrollTop: the replacement scroller
409	  // starts at zero after the reader unmounted the list, so using the captured
410	  // scrollTop would double-count the original offset. anchor.scrollTop remains
411	  // only as the missing-row fallback above.
412	  scroller.scrollTop = scroller.scrollTop + (relativeTop - anchor.offsetTop);
413	}
414	
415	watch(
416	  () => [props.rows.map((row) => rowKey(row.ref)), props.focusedRef] as const,
417	  async () => {
418	    await nextTick();
419	    if (!listHasFocus) return;
420	    // The focused row was removed from the list (e.g. archived out of the inbox
421	    // overlay): keep DOM focus predictable by moving it to the row matching the
422	    // composable's resolved focus reference instead of dropping it to the body.
423	    const focusedStillPresent = lastFocusedKey !== null && rowEls.has(lastFocusedKey);
424	    if (!focusedStillPresent && props.focusedRef) focusRef(props.focusedRef);
425	  },
426	);
427	
428	defineExpose({ focusRef, captureAnchor, restoreAnchor });
429	</script>
430	
431	<template>
432	  <ul class="inbox-list inbox-scroll" role="list" :aria-label="context === 'search' ? 'Search results' : context === 'starred' ? 'Cached Starred conversations' : context === 'done' ? 'Cached Done conversations' : context === 'saved' ? 'Saved split conversations' : 'Inbox conversations'" ref="listEl">
433	    <template v-for="item in items" :key="item.kind === 'group' ? `group-${item.id}` : rowKey(item.row.ref)">
434	      <li
435	        v-if="item.kind === 'group'"
436	        class="row-group"
437	        role="presentation"
438	      >{{ item.caption }}</li>
439	      <li
440	        v-else
441	        role="listitem"
442	        class="inbox-row"
443	        :class="{
444	          focused: isFocused(item.row),
445	          selected: isSelected(item.row),
446	          'meta-compact': isCompactRow(item.row),
447	          'actions-open': isActionsOpen(item.row),
448	          'actions-up': isPanelUpward(item.row),
449	        }"
450	        :aria-current="isFocused(item.row) ? 'true' : undefined"
451	        :tabindex="tabIndexFor(item.row, item.index)"
452	        :data-test="`conversation-row-${item.row.ref.conversationId}`"
453	        :ref="(el) => setRowRef(el, rowKey(item.row.ref))"
454	        @focusin="onFocusIn($event, item.row)"
455	        @focusout="onFocusOut"
456	        @keydown.escape="onRowKeydown($event, item.row)"
457	        @click="onRowClick($event, item.row)"
458	      >
459	        <!-- UX-05 selection control: a native labelled checkbox inside the
460	             listitem; it stops propagation and never opens the row. No
461	             aria-selected on listitem (invalid for role=listitem); aria-current
462	             stays the focus cue and the selected class is not color-only. -->
463	        <input
464	          type="checkbox"
465	          class="row-select"
466	          :data-test="`row-select-${item.row.ref.conversationId}`"
467	          :checked="isSelected(item.row)"
468	          :aria-label="`Select ${item.row.subject}`"
469	          @click.stop
470	          @change="emit('selectToggle', item.row.ref)"
471	        />
472	        <span class="row-sender" :class="{ unread: item.row.isRead === false }">{{ senderLabel(item.row) }}</span>
473	        <span class="row-subject-snippet">
474	          <span class="row-subject">{{ item.row.subject }}</span>
475	          <span class="row-preview">{{ item.row.preview }}</span>
476	        </span>
477	        <span class="row-meta">
478	          <span
479	            v-if="item.row.pendingOperationId"
480	            class="row-pending"
481	            data-test="row-pending"
482	            role="status"
483	          >Pending…</span>
484	          <span
485	            v-if="props.showReadState || props.showReadControls"
486	            class="row-read-state"
487	            :data-test="item.row.isRead === undefined ? 'row-read-unknown' : item.row.isRead ? 'row-read' : 'row-unread'"
488	            :aria-label="item.row.isRead === undefined ? 'Read state unknown' : undefined"
489	          >{{ readStateLabel(item.row) }}</span>
490	          <span
491	            v-if="item.row.stars && (item.row.stars.starredMessages > 0 || item.row.stars.knownMessages < item.row.stars.totalMessages || item.row.stars.totalMessages === 0)"
492	            class="row-read-state" data-test="row-stars" role="img"
493	            :aria-label="`${item.row.stars.starredMessages > 0 ? 'Starred' : 'Star state unknown'}; effective star values known for ${item.row.stars.knownMessages} of ${item.row.stars.totalMessages} cached messages; may include pending intent`"
494	            :title="`Effective star values known for ${item.row.stars.knownMessages} of ${item.row.stars.totalMessages} cached messages; pending intent is not provider confirmation`"
495	          >{{ item.row.stars.starredMessages > 0 ? '★' : 'Star unknown' }}{{ item.row.stars.knownMessages < item.row.stars.totalMessages ? ' (partial)' : '' }}</span>
496	          <span class="row-time">{{ compactDateLabel(item.row.lastMessageAt) }}</span>
497	          <button
498	            v-if="hasRowActions()"
499	            type="button"
500	            class="row-actions-toggle"
501	            :data-test="`row-actions-toggle-${item.row.ref.conversationId}`"
502	            aria-label="More actions"
503	            :aria-expanded="isActionsOpen(item.row) ? 'true' : 'false'"
504	            :aria-controls="actionsPanelId(item.row)"
505	            @click.stop="toggleActions(item.row)"
506	          >More</button>
507	          <span
508	            v-if="hasRowActions()"
509	            :id="actionsPanelId(item.row)"
510	            class="row-actions"
511	            role="group"
512	            aria-label="Row actions"
513	          >
514	            <template v-if="props.showReadControls && item.row.isRead === undefined">
515	              <button type="button" :data-test="`row-mark-read-${item.row.ref.conversationId}`" aria-label="Mark read" @click.stop="emit('setRead', item.row.ref, true)">Read</button>
516	              <button type="button" :data-test="`row-mark-unread-${item.row.ref.conversationId}`" aria-label="Mark unread" @click.stop="emit('setRead', item.row.ref, false)">Unread</button>
517	            </template>
518	            <button
519	              v-else-if="props.showReadControls"
520	              type="button"
521	              :data-test="`row-toggle-read-${item.row.ref.conversationId}`"
522	              @click.stop="emit('setRead', item.row.ref, !item.row.isRead)"
523	            >Mark {{ item.row.isRead ? 'unread' : 'read' }}</button>
524	            <button
525	              v-if="props.actionsEnabled && context !== 'starred'"
526	              type="button"
527	              class="row-archive-action"
528	              :data-test="`row-archive-${item.row.ref.conversationId}`"
529	              :title="actionLabel(context === 'done' ? 'unarchive' : 'archive')"
