  await new Promise(r => setTimeout(r, 400));
  const out = [];
  const list = document.querySelector('.inbox-scroll');
  const lr = list.getBoundingClientRect();
  for (const id of ['conv-01','conv-02','conv-03']) {
    const row = document.querySelector(`[data-test="conversation-row-${id}"]`);
    const r = row.getBoundingClientRect();
    const q = (s) => { const e = row.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect(); return { x: +(b.left - lr.left).toFixed(1), w: +b.width.toFixed(1) }; };
    const cs = (s, p) => getComputedStyle(row.querySelector(s))[p];
    out.push({ id, rowH: r.height, inset: r.left - lr.left, insetR: lr.right - list.clientLeft - r.right - (list.offsetWidth - list.clientWidth), sender: q('.row-sender'), subject: q('.row-subject'), preview: q('.row-preview'), time: q('.row-time'), dot: q('.row-read-state'), senderWeight: cs('.row-sender','fontWeight'), font: cs('.row-sender','fontSize'), previewColor: cs('.row-preview','color'), bg: getComputedStyle(row).backgroundColor, shadow: getComputedStyle(row).boxShadow });
  }
  const g = document.querySelector('.row-group'); const gb = g.getBoundingClientRect();
