  const vueUrl = performance.getEntriesByType('resource').map((x) => x.name).find((n) => n.includes('/node_modules/.vite/deps/vue.js'));
  const { createApp } = await import(vueUrl);
  const { default: App } = await import('/src/App.vue');
  const { createBrowserFakeMailClient } = await import('/src/lib/ipc/browser-fake.ts');
  const mount = async () => {
    const root = document.querySelector('#app');
    root.__vue_app__?.unmount();
    const fake = createBrowserFakeMailClient();
    fake.controls.setAccount({ mode: 'gmail', connection: 'connected', emailAddress: 'review@example.test', mutationAccess: 'enabled', coverageLimit: 100 });
    const client = { ...fake, listConversations: async () => { const s = await fake.listConversations(); return { ...s, conversations: s.conversations.map((r) => r.ref.conversationId === 'conv-01' || r.ref.conversationId === 'conv-17' ? { ...r, lastMessageAt: '2001-09-30T09:00:00Z' } : r) }; } };
    createApp(App, { client, mode: 'browser-preview' }).mount(root);
    await new Promise(r => setTimeout(r, 400));
    for (const id of ['conv-01','conv-05','conv-17']) fake.controls.markReadUnknown(id);
    fake.controls.behavior.hold = true;
    const snap = await fake.listConversations();
    for (const id of ['conv-01','conv-17']) await fake.setArchived({ conversation: snap.conversations.find(r => r.ref.conversationId === id).ref, archived: false, requestId: 'p-' + id });
    await new Promise(r => setTimeout(r, 300));
  };
  const res = [];
  for (const px of [16, 20]) {
    document.documentElement.style.fontSize = px + 'px';
    await mount();
    const row = document.querySelector('[data-test="conversation-row-conv-01"]');
    const sub = row.querySelector('.row-subject');
    res.push({ px, compact: row.classList.contains('meta-compact'), sw: row.scrollWidth, cw: row.clientWidth, subjW: Math.round(sub.getBoundingClientRect().width), h: row.getBoundingClientRect().height });
  }
  return res;
})()

