S=/private/tmp/claude-501/-Users-sofianebebert-workspace-worktrees-email-os-t3-7080b790/55d0556b-179f-4a4a-bdc1-c9411cb45f29/scratchpad; cat > $S/shot.mjs <<'EOF'
import { spawn } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
const [chrome, outDir] = process.argv.slice(2);
const profile = mkdtempSync(join(outDir, 'prof-'));
const proc = spawn(chrome, ['--headless=new', '--remote-debugging-port=0', '--no-first-run', `--user-data-dir=${profile}`, '--force-device-scale-factor=2', 'about:blank'], { stdio: 'ignore' });
let port; for (let i = 0; i < 100 && !port; i++) { await new Promise(r => setTimeout(r, 100)); try { port = readFileSync(join(profile, 'DevToolsActivePort'), 'utf8').split('\n')[0]; } catch {} }
const page = (await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()).find(t => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl); await new Promise(r => ws.addEventListener('open', r, { once: true }));
let id = 0; const wait = new Map();
ws.addEventListener('message', e => { const m = JSON.parse(e.data); if (m.id && wait.has(m.id)) { wait.get(m.id)(m); wait.delete(m.id); } });
const cmd = (method, params = {}) => new Promise(r => { const i = ++id; wait.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const js = async (expression) => { const r = await cmd('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.result?.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails)); return r.result?.result?.value; };
const sleep = ms => new Promise(r => setTimeout(r, ms));
await cmd('Page.enable');
for (const width of [1030, 1280]) {
  await cmd('Emulation.setDeviceMetricsOverride', { width, height: 800, deviceScaleFactor: 2, mobile: false });
  await cmd('Page.navigate', { url: 'http://localhost:5199/' }); await sleep(1500);
  await js(`(async () => {
    const vueUrl = performance.getEntriesByType('resource').map((x) => x.name).find((n) => n.includes('/node_modules/.vite/deps/vue.js'));
    const { createApp } = await import(vueUrl);
    const { default: App } = await import('/src/App.vue');
    const { createBrowserFakeMailClient } = await import('/src/lib/ipc/browser-fake.ts');
    const root = document.querySelector('#app'); root.__vue_app__?.unmount();
    const fake = createBrowserFakeMailClient();
    fake.controls.setAccount({ mode: 'gmail', connection: 'connected', emailAddress: 'review@example.test', mutationAccess: 'enabled', coverageLimit: 100 });
    createApp(App, { client: fake, mode: 'browser-preview' }).mount(root);
    await new Promise(r => setTimeout(r, 500));
    fake.controls.markReadUnknown('conv-03');
    await new Promise(r => setTimeout(r, 300));
    document.querySelector('[data-test="conversation-row-conv-02"]').focus();
  })()`);
  // hover conv-05 to show the hover reveal
  const r = await js(`(() => { const b = document.querySelector('[data-test="conversation-row-conv-05"] .row-subject').getBoundingClientRect(); return { x: b.left + 10, y: b.top + 5 }; })()`);
  await cmd('Input.dispatchMouseEvent', { type: 'mouseMoved', x: r.x, y: r.y });
  await sleep(300);
  const shot = await cmd('Page.captureScreenshot', { format: 'png' });
  writeFileSync(join(outDir, `rows-${width}.png`), Buffer.from(shot.result.data, 'base64'));
}
ws.close(); proc.kill(); await sleep(300); rmSync(profile, { recursive: true, force: true });
console.log('done');
EOF
